import { useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Link, Route, Switch, useLocation, useParams } from 'wouter';
import {
  AlertCircle, ArrowLeft, ArrowRight, BarChart3, Bell, BriefcaseBusiness,
  CalendarDays, Check, CheckCircle2, ChevronLeft, ChevronRight,
  CircleDollarSign, ClipboardList, Clock3, Download, FileBarChart,
  FileText, Filter, HandCoins, Home, Landmark, LayoutDashboard, LogOut,
  Menu, Phone, Plus, Printer, Receipt, RefreshCw, Search,
  Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Target, TrendingUp,
  UserPlus, Users, Wallet, X
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

type Status = 'active' | 'extended' | 'completed' | 'overdue';
type PaymentStatus = 'paid' | 'partial' | 'missed' | 'pending';
type CollectionType = 'Daily' | 'Monthly' | 'Lump Sum';

interface Borrower {
  id: string; name: string; phone: string; address: string; barangay: string;
  status: 'Active' | 'Overdue' | 'Completed'; notes: string;
}
interface Partner { id: string; name: string; contact: string; share: number; notes: string; }
interface Loan {
  id: string; number: string; borrowerId: string; principal: number; rate: number;
  interest: number; totalDue: number; paid: number; collectionType: CollectionType;
  targetDays: number; maxDays: number; loanDate: string; targetDate: string;
  maturityDate: string; status: Status; partnerId?: string;
}
interface Payment {
  id: string; date: string; borrowerId: string; loanId: string; expected: number;
  paid: number; method: string; notes: string; status: PaymentStatus;
}
interface Toast { id: number; title: string; message: string; tone?: 'success' | 'info' | 'warning'; }
type ModalState = 'borrower' | 'partner' | 'loan' | 'payment' | null;

const money = (value: number) => `₱${Math.round(value).toLocaleString('en-PH')}`;
const shortDate = (value: string) => new Date(`${value}T00:00:00`).toLocaleDateString('en-PH', { month: 'short', day: 'numeric', year: 'numeric' });
const isoDay = (offset = 0) => {
  const date = new Date();
  date.setDate(date.getDate() + offset);
  return date.toISOString().slice(0, 10);
};
const today = isoDay();
const statusLabel = (value: string) => value.charAt(0).toUpperCase() + value.slice(1);
const initials = (name: string) => name.split(' ').map((part) => part[0]).slice(0, 2).join('');

